#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

namespace Campground.Shared.Registry
{
    /// <summary>What a plugin says about itself.</summary>
    internal sealed record PluginStatus(bool Enabled, bool EmergencyDisabled, string? Note = null);

    /// <summary>One Campground plugin as other plugins see it.</summary>
    internal sealed record CampgroundPlugin(
        string Id,
        string Name,
        string Version,
        string SharedVersion,
        IReadOnlyList<string> Capabilities,
        PluginStatus Status);

    /// <summary>
    /// §3.1 — which Campground plugins are installed, their versions, state and capabilities.
    /// </summary>
    internal static class PluginRegistry
    {
        private const string SectionName = "plugins";

        /// <summary>
        /// Announces this plugin. Call once at startup (the plugin constructor or service registrator).
        /// <paramref name="status"/> is asked fresh each time someone lists plugins.
        /// </summary>
        internal static void Announce(string id, string name, string version, IEnumerable<string> capabilities, Func<PluginStatus> status)
        {
            var caps = capabilities.ToArray();
            CampgroundRegistry.Section(SectionName)[id] = new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["id"] = id,
                ["name"] = name,
                ["version"] = version,
                ["sharedVersion"] = CampgroundShared.Version,
                ["capabilities"] = caps,
                ["status"] = (Func<JsonElement>)(() => CampgroundRegistry.ToJson(SafeStatus(status))),
            };
        }

        /// <summary>Every announced plugin, this one included. Never throws.</summary>
        internal static IReadOnlyList<CampgroundPlugin> List()
        {
            var list = new List<CampgroundPlugin>();
            foreach (var value in CampgroundRegistry.Section(SectionName).Values)
            {
                if (value is not IReadOnlyDictionary<string, object?> r)
                {
                    continue;
                }

                PluginStatus status;
                try
                {
                    var f = CampgroundRegistry.Get<Func<JsonElement>>(r, "status");
                    status = (f == null ? null : CampgroundRegistry.FromJson<PluginStatus>(f())) ?? new PluginStatus(true, false, "status unknown");
                }
                catch (Exception)
                {
                    status = new PluginStatus(true, false, "status unavailable");
                }

                list.Add(new CampgroundPlugin(
                    CampgroundRegistry.Get<string>(r, "id") ?? "?",
                    CampgroundRegistry.Get<string>(r, "name") ?? "?",
                    CampgroundRegistry.Get<string>(r, "version") ?? "?",
                    CampgroundRegistry.Get<string>(r, "sharedVersion") ?? "?",
                    CampgroundRegistry.Get<string[]>(r, "capabilities") ?? Array.Empty<string>(),
                    status));
            }

            return list.OrderBy(p => p.Name, StringComparer.OrdinalIgnoreCase).ToList();
        }

        /// <summary>Whether a plugin is installed and announced (enabled or not).</summary>
        internal static bool IsInstalled(string id) => CampgroundRegistry.Section(SectionName).ContainsKey(id);

        private static PluginStatus SafeStatus(Func<PluginStatus> status)
        {
            try
            {
                return status();
            }
            catch (Exception ex)
            {
                return new PluginStatus(true, false, "status error: " + ex.GetType().Name);
            }
        }
    }

